import java.util.*;

class Solution {
    public int carFleet(int target, int[] position, int[] speed) {
        int n = position.length;
        int[][] cars = new int[n][2];

        for (int i = 0; i < n; i++) {
            cars[i][0] = position[i];
            cars[i][1] = speed[i];
        }

        Arrays.sort(cars, (a, b) -> Integer.compare(b[0], a[0]));

        int fleets = 0;
        double slowestFleetTime = 0.0;

        for (int[] car : cars) {
            double arrivalTime = (double) (target - car[0]) / car[1];
            if (arrivalTime > slowestFleetTime) {
                fleets++;
                slowestFleetTime = arrivalTime;
            }
        }

        return fleets;
    }
}

import java.util.*;

class Solution {
    public int carFleet(int target, int[] position, int[] speed) {
        int n = position.length;
        double[][] cars = new double[n][2];

        for (int i = 0; i < n; i++) {
            cars[i][0] = position[i];
            cars[i][1] = (double) (target - position[i]) / speed[i];
        }

        Arrays.sort(cars, (a, b) -> Double.compare(b[0], a[0]));

        Deque<Double> fleetTimes = new ArrayDeque<>();
        for (double[] car : cars) {
            double arrivalTime = car[1];
            if (fleetTimes.isEmpty() || arrivalTime > fleetTimes.peek()) {
                fleetTimes.push(arrivalTime);
            }
        }

        return fleetTimes.size();
    }
}

import java.util.*;

class Solution {
    public int carFleet(int target, int[] position, int[] speed) {
        double[] timeAtPosition = new double[target];
        Arrays.fill(timeAtPosition, -1.0);

        for (int i = 0; i < position.length; i++) {
            timeAtPosition[position[i]] = (double) (target - position[i]) / speed[i];
        }

        int fleets = 0;
        double slowestAhead = 0.0;

        for (int pos = target - 1; pos >= 0; pos--) {
            double arrivalTime = timeAtPosition[pos];
            if (arrivalTime < 0.0) {
                continue;
            }
            if (arrivalTime > slowestAhead) {
                fleets++;
                slowestAhead = arrivalTime;
            }
        }

        return fleets;
    }
}

import java.util.*;

class Solution {
    public int carFleet(int target, int[] position, int[] speed) {
        int n = position.length;
        double[][] cars = new double[n][2];

        for (int i = 0; i < n; i++) {
            cars[i][0] = position[i];
            cars[i][1] = (double) (target - position[i]) / speed[i];
        }

        Arrays.sort(cars, Comparator.comparingDouble(car -> car[0]));

        int fleets = 0;
        for (int i = n - 1; i >= 0; i--) {
            double maxAheadTime = 0.0;
            for (int j = i + 1; j < n; j++) {
                maxAheadTime = Math.max(maxAheadTime, cars[j][1]);
            }
            if (cars[i][1] > maxAheadTime) {
                fleets++;
            }
        }

        return fleets;
    }
}
